def transform(wb):
    ws = wb['Sheet1']
    max_row = ws.max_row
    blocks = []
    start = None
    for r in range(2, max_row + 1):
        a = ws.cell(row=r, column=1).value
        if a == '@9T' or a == 'SAL' or a == 'T9A':
            if start is None:
                start = r
        else:
            if start is not None:
                blocks.append((start, r - start))
                start = None
    if start is not None:
        blocks.append((start, max_row - start + 1))
    deleted = 0
    for start, amount in blocks:
        ws.delete_rows(start - deleted, amount)
        deleted += amount
    return None
